-- An AI-written CareBase course joins the central catalog as soon as it is drafted, so its exact material can be
-- preserved, reviewed and published through the same governed commands as every other CareBase course.
-- hub.stage_learning_source refuses a course without a catalog mapping, and before this nothing created one for a
-- course CareBase's AI wrote (only governed creation registered its courses).
--
-- Only a fresh AI draft qualifies: version 1, still a draft, marked AI-generated by CareBase, exactly as
-- create_course_from_ai_draft_delegated writes it. The server reads the material from CareBase itself; the browser
-- names only the course and version. The mapping matches governed creation's, so a repeat is acknowledged instead of
-- creating a second catalog item, and an existing different mapping is never overwritten.
set local lock_timeout='10s';

create function private.register_generated_course(p_course_id uuid,p_version_id uuid,p_payload text,p_source_revision text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor jsonb; editor uuid; doc jsonb; item uuid; existing uuid;
begin
  actor:=private.course_creation_actor(); editor:=(actor->>'user_id')::uuid;
  doc:=private.validate_governed_learning_source(p_payload,p_source_revision);
  if (doc->>'sourceCourseId')::uuid is distinct from p_course_id or (doc->>'sourceVersionId')::uuid is distinct from p_version_id then
    raise exception 'The course material does not match the requested course.' using errcode='22023'; end if;
  if doc->>'publicationState'<>'draft' or doc->>'sourceVersionState'<>'draft' or doc->'sourceVersionNumber'<>'1'::jsonb
    or doc->'version'->'aiGenerated' is distinct from 'true'::jsonb then
    raise exception 'Only a new AI-written draft joins the catalog this way.' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('hub-course-create:'||p_course_id::text,0));
  item:=md5('penntrain-course-item:'||p_course_id::text)::uuid;
  select l.content_item_id into existing from hub.course_links l where lower(l.penntrain_course_id)=p_course_id::text;
  if found then
    if existing is distinct from item then raise exception 'Review the existing catalog mapping; it cannot be overwritten.' using errcode='40001'; end if;
    return jsonb_build_object('itemId',item,'registered',false);
  end if;
  if exists(select 1 from hub.content_items where id=item or content_key='carebase-course.'||p_course_id::text) then
    raise exception 'Review the existing catalog mapping; it cannot be overwritten.' using errcode='40001'; end if;
  insert into hub.content_items(id,content_key,kind,status,access_level,source_system,owner_product_id,owner_team,created_by)
    values(item,'carebase-course.'||p_course_id::text,'course','draft','staff','penntrain',
      (select id from hub.products where slug='carebase'),'CareMetric Learning',editor);
  insert into hub.course_links(content_item_id,penntrain_course_id,source_version,launch_path,duration_minutes)
    values(item,p_course_id::text,p_version_id::text,'/app/courses/'||p_course_id::text,(doc->'course'->>'estimatedDurationMinutes')::integer);
  insert into private.audit_events(actor_id,action,entity_type,entity_id,metadata)
    values(editor,'learning.generation.registered','content_item',item,jsonb_build_object('course_id',p_course_id,'version_id',p_version_id));
  return jsonb_build_object('itemId',item,'registered',true);
end; $$;
revoke all on function private.register_generated_course(uuid,uuid,text,text) from public,anon,authenticated,service_role,hub_app_server;
grant execute on function private.register_generated_course(uuid,uuid,text,text) to hub_app_server;
